/**
 * SERVER-SIDE ONLY ENDPOINT: Supabase Auth Send SMS Hook
 * Receives OTP generated by Supabase Auth GoTrue Server
 * Dispatches DLT-approved SMS via Fast2SMS API (DLT Route)
 * 
 * NEVER EXPOSES FAST2SMS_API_KEY TO BROWSER / CLIENT
 */
export async function handleSendSmsHook(reqBody, headers = {}) {
  // Optional Signature / Secret Authorization Check
  const hookSecret = process.env.SEND_SMS_HOOK_SECRET;
  if (hookSecret) {
    const authHeader = headers['authorization'] || headers['Authorization'] || headers['x-supabase-auth-secret'] || '';
    const token = authHeader.replace(/^Bearer\s+/i, '').trim();
    if (token && token !== hookSecret) {
      console.warn('[AUTH SMS] Unauthorized token signature');
      return {
        status: 401,
        body: { error: 'Unauthorized: Invalid Supabase Auth Hook Secret.' }
      };
    }
  }

  // Parse stringified payload if received as string
  let payload = reqBody;
  if (typeof payload === 'string') {
    try {
      payload = JSON.parse(payload);
    } catch (e) {
      console.error('[AUTH SMS] Failed to parse string body');
    }
  }

  console.info('[AUTH SMS] Supabase SMS hook received');

  // Extract User Phone and Supabase-generated OTP from payload
  const rawPhone = payload?.user?.phone || payload?.phone || payload?.record?.phone || payload?.user_phone || '';
  const otpCode = payload?.sms?.otp || payload?.otp || payload?.record?.otp || payload?.sms_otp || payload?.token || '';

  if (!rawPhone || !otpCode) {
    console.error('[AUTH SMS] Bad Request: Missing phone number or OTP in hook payload');
    return {
      status: 400,
      body: { error: 'Bad Request: Missing phone number or OTP in hook payload.' }
    };
  }

  // Normalize phone number to 10-digit Indian mobile format
  const cleanDigits = String(rawPhone).replace(/\D/g, '');
  const tenDigitPhone = cleanDigits.length >= 10 ? cleanDigits.slice(-10) : cleanDigits;

  if (tenDigitPhone.length !== 10) {
    console.error('[AUTH SMS] Invalid 10-digit phone length');
    return {
      status: 400,
      body: { error: `Invalid phone format: ${rawPhone}` }
    };
  }

  // Sanitized phone for secure logging (e.g., +91XXXXXX5902)
  const maskedPhone = `+91XXXXXX${tenDigitPhone.slice(-4)}`;
  console.info(`[AUTH SMS] Phone: ${maskedPhone}`);
  console.info('[AUTH SMS] Sending via Fast2SMS DLT');
  console.info('[AUTH SMS] Sender ID: HELTEX');
  console.info('[AUTH SMS] Message ID: 206293');
  console.info('[AUTH SMS] Variable count: 1');

  // Retrieve Fast2SMS API Key from server environment
  const fast2smsApiKey = process.env.FAST2SMS_API_KEY || 'H6n9y6LlTeG4ihzEv6J6D8iPOehmjBEUb7DV1s3Luuay0s7zdbYgGKrf2W1r';

  // Build Fast2SMS DLT API Request
  const senderId = 'HELTEX';
  const dltMessageId = '206293'; // Approved Health Express DLT template ID

  try {
    const fast2smsUrl = new URL('https://www.fast2sms.com/dev/bulkV2');
    fast2smsUrl.searchParams.append('authorization', fast2smsApiKey);
    fast2smsUrl.searchParams.append('route', 'dlt');
    fast2smsUrl.searchParams.append('sender_id', senderId);
    fast2smsUrl.searchParams.append('message', dltMessageId);
    fast2smsUrl.searchParams.append('variables_values', String(otpCode));
    fast2smsUrl.searchParams.append('numbers', tenDigitPhone);

    const response = await fetch(fast2smsUrl.toString(), {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    });

    const resJson = await response.json();
    console.info(`[AUTH SMS] Fast2SMS response status: ${response.status}`);

    if (!response.ok || resJson.return === false) {
      console.error('[AUTH SMS] Fast2SMS delivery error status:', response.status, 'message:', resJson.message || resJson);
      return {
        status: 500,
        body: { error: 'Fast2SMS DLT OTP delivery failed.' }
      };
    }

    console.info('[AUTH SMS] SMS dispatched successfully');
    // Return HTTP 200 OK with empty JSON object required by Supabase Auth Hook
    return {
      status: 200,
      body: {}
    };
  } catch (err) {
    console.error('[AUTH SMS] Send Hook Exception:', err.message || err);
    return {
      status: 500,
      body: { error: 'Internal server error sending DLT SMS.' }
    };
  }
}

/**
 * VERCEL SERVERLESS FUNCTION HANDLER
 */
export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed. Use POST.' });
  }

  let body = req.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {}
  }

  const result = await handleSendSmsHook(body, req.headers);
  return res.status(result.status).json(result.body);
}
